// Convierte la respuesta base64url de Gmail API a binario n8n
const base64url = $json.data || '';
if (!base64url) throw new Error('Gmail API devolvió data vacía para el adjunto Excel.');

// base64url → base64 estándar
const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
const buffer = Buffer.from(base64, 'base64');

const excelInfo = $node["Call 'Data interpreter'"].json;
const fileName  = excelInfo.excelFileName || 'adjunto.xlsx';
const mimeType  = excelInfo.excelMimeType || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [{
  json: {
    messageId:    excelInfo.messageId,
    emailFrom:    excelInfo.emailFrom,
    emailSubject: excelInfo.emailSubject,
    hasExcel:     true,
    hasZip:       excelInfo.hasZip,
    excelFileName: fileName
  },
  binary: { excelFile: binaryData }
}];

const items = $input.all();
const REQUIRED = ['OBLIGACION', 'CEDULA', 'NOMBRE', 'CAPITAL', 'INTERES'];

if (!items || items.length === 0) {
  return [{ json: { isValid: false, validationError: 'El Excel no tiene datos en Hoja2.', rows: [], rowCount: 0 } }];
}

const validRows = items.map(i => i.json).filter(r => Object.values(r).some(v => v !== null && v !== undefined && v !== ''));

if (validRows.length === 0) {
  return [{ json: { isValid: false, validationError: 'Todas las filas de Hoja2 están vacías.', rows: [], rowCount: 0 } }];
}

const cols = Object.keys(validRows[0]);
const missing = REQUIRED.filter(c => !cols.includes(c));

if (missing.length > 0) {
  return [{ json: { isValid: false, validationError: `Columnas faltantes: ${missing.join(', ')}. Detectadas: ${cols.slice(0, 10).join(', ')}`, rows: [], rowCount: 0 } }];
}

return [{ json: { isValid: true, rows: validRows, rowCount: validRows.length, columns: cols } }];

const rows = $json.rows;
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const hoy = new Date();
const fechaHoy = `${hoy.getDate()} de ${MESES[hoy.getMonth()]} del ${hoy.getFullYear()}`;

const fmt = (val) => {
  if (val === null || val === undefined || val === '') return '';
  const n = parseFloat(String(val).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? String(val) : n.toLocaleString('es-CO');
};

const fmtFecha = (val) => {
  if (!val) return '';
  try {
    const d = new Date(val);
    if (!isNaN(d.getTime())) return `${d.getDate()} de ${MESES[d.getMonth()]} del ${d.getFullYear()}`;
  } catch(e) {}
  return String(val);
};

return rows.map(row => ({ json: {
  'FECHA DE ASIGNACION':                fechaHoy,
  'TIPO DE JUZGADO':                    'PROMISCUO MUNICIPAL',
  'CIUDAD DE JUZGADO':                  '',
  'CUANTIA':                            'MINIMA',
  'OBLIGACION':                         row.OBLIGACION || '',
  'IDENTIFICACION':                     row.CEDULA || '',
  'NOMBRE':                             row.NOMBRE || '',
  'CAPITAL':                            fmt(row.CAPITAL),
  'INTERES':                            fmt(row.INTERES),
  'FECHA MORA':                         fmtFecha(row.MORA),
  'FECHA DE SUSCRIPCION':               '',
  'VALOR CUANTIA':                      fmt(row['TOTAL INTERES'] || row.TOTAL || ''),
  'DIRECCION DE RESIDENCIA':            '',
  'DIRECCION ELECTRONICA':              '',
  'NIT EMPRESA TT':                     '',
  'NOMBRE EMPRESA TT':                  '',
  'DIRECCION ELECTRONICA EMPLEADOR':    '',
  'PLACA':                              '',
  'SERVICIO':                           '',
  'CLASE':                              '',
  'MARCA':                              '',
  'LINEA':                              '',
  'MODELO':                             '',
  'COLOR':                              '',
  'SERIE':                              '',
  'MOTOR':                              '',
  'CHASIS':                             '',
  'TIPO DE CARROCERIA':                 '',
  'STRIA MCPAL\nTTOyTTE':               '',
  'DIRECCION ELECTRONICA DEL TRANSITO': ''
}}));

const base64url = $json.data || '';
if (!base64url) throw new Error('Gmail API devolvió data vacía para el adjunto ZIP.');

const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
const buffer = Buffer.from(base64, 'base64');

const zipInfo  = $node["Call 'Data interpreter'"].json;
const fileName = zipInfo.zipFileName || 'adjunto.zip';
const mimeType = zipInfo.zipMimeType || 'application/zip';

const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [{
  json: {
    messageId:    zipInfo.messageId,
    emailFrom:    zipInfo.emailFrom,
    emailSubject: zipInfo.emailSubject,
    zipFileName:  fileName
  },
  binary: { zipFile: binaryData }
}];

// Extrae la "Tabla de Casos" del cuerpo HTML del correo de Libertador.
// Colócalo después de "Es una asignacion?" (salida true).
const meta = $node["Call 'Data interpreter'"].json;      // messageId, emailFrom, subject…
const html = $json.emailBodyHtml || meta.emailBodyHtml || '';
if (!html) throw new Error('El correo no trae parte HTML (emailBodyHtml vacío).');

const limpiar = (s) => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ').trim();

const filasDe = (tabla) =>
  (tabla.match(/<tr[\s\S]*?<\/tr>/gi) || [])
    .map(tr => (tr.match(/<t[dh][\s\S]*?<\/t[dh]>/gi) || []).map(limpiar))
    .filter(r => r.length);

const tablas = html.match(/<table[\s\S]*?<\/table>/gi) || [];
let tabla = tablas.find(t => {
  const x = limpiar(t).toLowerCase();
  return x.includes('solicitud') && (x.includes('alistamiento') || x.includes('siniestro'));
}) || tablas[tablas.length - 1];
if (!tabla) throw new Error('No se encontró la Tabla de Casos en el HTML.');

const rows = filasDe(tabla);
const hIdx = rows.findIndex(r => r.join(' ').toLowerCase().includes('solicitud'));
const header = (rows[hIdx] || []).map(h => h.toLowerCase());
let datos = rows.slice(hIdx + 1).filter(r => r.some(c => c));
// Si una fila trae un número de fila de más al inicio ("1"), se descarta.
datos = datos.map(r => (r.length === header.length + 1 && /^\d{1,3}$/.test(r[0])) ? r.slice(1) : r);

const idx = (...k) => header.findIndex(h => k.some(x => h.includes(x)));
const iSol = idx('solicitud'), iTipo = idx('alistamiento','tipo'), iEst = idx('estado','siniestro'),
      iDeu = idx('deuda'), iCan = idx('canon'), iObs = idx('observ');
const num = (s) => Number(String(s || '').replace(/[^\d]/g, '')) || 0;

const casos = datos.map(r => {
  const noSolicitud      = iSol  >= 0 ? r[iSol]  : '';
  const tipoAlistamiento = iTipo >= 0 ? r[iTipo] : '';

  // --- Clasificación (mixto / conciliación) ---
  const T = tipoAlistamiento.toUpperCase();
  const esMixto         = /\bMIXTO\b/.test(T);
  const conConciliacion = /CONCILIAC/.test(T);

  let numFilas = 1;
  let procesos = [T || 'UNICO'];
  if (esMixto && conConciliacion) { numFilas = 3; procesos = ['CONCILIACION', 'RESTITUCION', 'EJECUTIVO']; }
  else if (esMixto)               { numFilas = 2; procesos = ['RESTITUCION', 'EJECUTIVO']; }

  return {
    messageId:        meta.messageId,
    emailFrom:        meta.emailFrom,
    emailSubject:     meta.emailSubject,
    noSolicitud,
    tipoAlistamiento,
    estadoSiniestro:  iEst >= 0 ? r[iEst] : '',
    valorDeuda:       iDeu >= 0 ? num(r[iDeu]) : 0,
    valorCanon:       iCan >= 0 ? num(r[iCan]) : 0,
    observaciones:    iObs >= 0 ? r[iObs] : '',
    // --- clasificación ---
    esMixto,
    conConciliacion,
    numFilas,
    procesos,
  };
}).filter(c => c.noSolicitud);

if (!casos.length) throw new Error('Se halló la tabla pero no se extrajeron filas.');

// Fecha de recepción en el formato del cuadro (DD/MM/AAAA).
const dd = (n) => String(n).padStart(2, '0');
const hoy = new Date();
const recibido = `${dd(hoy.getDate())}/${dd(hoy.getMonth() + 1)}/${hoy.getFullYear()}`;

// Un MIXTO no es un caso: son 2 o 3 procesos que van por separado. Se expande
// aquí para que cada proceso sea SU fila en el cuadro, repitiendo los datos del
// caso. `procesos` ya trae el desglose calculado arriba.
const filas = [];
for (const caso of casos) {
  const { procesos, numFilas, ...base } = caso;

  // El cuadro NO tiene columna para deuda ni para estado del siniestro, así que
  // van dentro de OBSERVACIONES, con el mismo formato "fecha TEXTO // TEXTO"
  // que ya usa esa columna.
  const partes = [`${recibido} ASIGNACION ${base.tipoAlistamiento || ''}`.trim()];
  if (base.estadoSiniestro) partes.push(`ESTADO SINIESTRO: ${base.estadoSiniestro}`);
  if (base.valorDeuda)      partes.push(`DEUDA: $${base.valorDeuda.toLocaleString('es-CO')}`);
  if (base.observaciones)   partes.push(base.observaciones);
  const observacionesSheet = partes.join(' // ');

  procesos.forEach((proceso, i) => {
    filas.push({
      ...base,
      recibido,
      proceso,
      procesoIndice:   i + 1,
      procesosDelCaso: procesos.length,
      observacionesSheet,
      claveFila: `${base.noSolicitud}-${proceso}`,
    });
  });
}

return filas.map(f => ({ json: f }));
